// Character-set model for the embedded-font generator (§8.7.7).
//
// A generated font carries only the glyphs you ask for, so "which characters"
// is the single biggest lever on flash size — and the one thing a count alone
// cannot answer. This module defines what can be selected and how selections
// combine.
//
// Three properties the model is built to hold:
//
//   * **Every set is auditable.** The building blocks come from Unicode's own
//     data (charsets-data.js, generated by tools/gen-charsets.mjs) or from a
//     literal list in that generator. None of them is a curated grab-bag whose
//     contents you have to take on faith.
//   * **Tiers never lose characters.** Han tiers are cumulative unions, so
//     moving from 常用漢字 to JIS level 2 can only ever add.
//   * **Han is per language, unioned.** Japanese, Simplified, Traditional and
//     Korean are different repertoires, not points on one scale. Each is chosen
//     independently and the results are unioned — which is also why "CJK" is
//     just another entry here rather than something that sits above Japanese.
//
// A selection is stored as a flat list of set ids. The UI groups them into
// axes and enforces "one tier per language", but nothing downstream needs to
// know that: resolving is always a union.
import { SET_RANGES, SET_COUNTS } from './charsets-data.js';

// "20-7E,A0" -> [0x20..0x7E, 0xA0]. Whitespace and empty items are ignored.
export function parseRanges(spec) {
  const out = [];
  for (const partRaw of String(spec).split(',')) {
    const part = partRaw.trim();
    if (!part) continue;
    const m = /^(?:U\+)?([0-9A-Fa-f]+)(?:\s*-\s*(?:U\+)?([0-9A-Fa-f]+))?$/.exec(part);
    if (!m) continue;
    const a = parseInt(m[1], 16);
    const b = m[2] === undefined ? a : parseInt(m[2], 16);
    for (let c = Math.min(a, b); c <= Math.max(a, b); c++) out.push(c);
  }
  return out;
}

// Codepoints of a literal string, surrogate pairs collapsed to one codepoint.
export const codepointsOf = (text) => [...String(text)].map((ch) => ch.codePointAt(0));

// --- the axes -------------------------------------------------------------
//
// `kind` drives the UI: 'multi' renders checkboxes, 'tier' renders one row per
// language with a mutually exclusive ladder of levels.

export const AXES = [
  {
    id: 'latin',
    kind: 'multi',
    sets: ['digits', 'ascii', 'latinExt', 'greek', 'cyrillic'],
  },
  {
    id: 'kana',
    kind: 'multi',
    sets: ['hiragana', 'katakana', 'katakanaHalf', 'jaPunct'],
  },
  {
    id: 'han',
    kind: 'tier',
    // Each language is independent; the chosen tiers are unioned.
    languages: [
      { id: 'ja', tiers: ['hanJa1', 'hanJa2', 'hanJa3', 'hanJa4'] },
      { id: 'cn', tiers: ['hanCn1', 'hanCn2'] },
      { id: 'tw', tiers: ['hanTw1', 'hanTw2'] },
      { id: 'ko', tiers: ['hanKo1', 'hanKo2'] },
      { id: 'all', tiers: ['hanAll'] },
    ],
  },
  {
    id: 'hangul',
    kind: 'tier',
    languages: [{ id: 'hangul', tiers: ['hangulKs', 'hangulAll'] }],
  },
  {
    id: 'symbols',
    kind: 'multi',
    sets: ['symUnits', 'symMath', 'symArrows', 'symShapes', 'symCurrency', 'symEnclosed', 'symMisc'],
  },
];

// id -> which tier ladder it belongs to, so choosing one level can clear the
// others without the caller knowing the axis layout.
const TIER_GROUP = new Map();
for (const axis of AXES) {
  if (axis.kind !== 'tier') continue;
  for (const lang of axis.languages) {
    for (const id of lang.tiers) TIER_GROUP.set(id, lang.tiers);
  }
}
export const tierSiblings = (id) => TIER_GROUP.get(id) || null;

// Every selectable set id, in axis order.
export const ALL_SET_IDS = AXES.flatMap((a) =>
  a.kind === 'multi' ? a.sets : a.languages.flatMap((l) => l.tiers));

export const countOf = (id) => SET_COUNTS[id] ?? 0;

// Codepoints are expanded lazily: the CJK sets run to twenty thousand entries
// each and a page that only generates ASCII should never pay for them.
const cache = new Map();
export function codepointsOfSet(id) {
  if (cache.has(id)) return cache.get(id);
  const spec = SET_RANGES[id];
  if (spec === undefined) return [];
  const cps = [...new Set(parseRanges(spec))].sort((a, b) => a - b);
  cache.set(id, cps);
  return cps;
}

// --- templates ------------------------------------------------------------
//
// One click for the cases people actually build. These are not a separate kind
// of set — they just fill in a selection, which stays editable afterwards.

// `sample` is the preview string the template switches to. Without it every
// template would preview the same characters and the difference between, say,
// a clock and a Japanese UI would be invisible — which is the whole point of
// looking at a preview.
export const TEMPLATES = [
  { id: 'clock', sets: ['digits'], text: ':./- ', sample: '12:34' },
  {
    id: 'clockJa',
    sets: ['digits', 'jaPunct'],
    text: ':./- 年月日時分秒曜月火水木金土日午前後',
    sample: '12:34 火曜日',
  },
  { id: 'sensor', sets: ['digits', 'symUnits'], text: ':./%+- ', sample: '25.6℃ 60%' },
  { id: 'latinUi', sets: ['ascii', 'latinExt', 'symUnits'], text: '', sample: 'Hello 25.6℃ 100%' },
  {
    id: 'japaneseUi',
    sets: ['ascii', 'hiragana', 'katakana', 'jaPunct', 'hanJa1', 'symUnits'],
    text: '',
    sample: 'こんにちは 25.6℃ 気温',
  },
  {
    id: 'japaneseFull',
    sets: ['ascii', 'latinExt', 'hiragana', 'katakana', 'jaPunct', 'hanJa4', 'symUnits', 'symMath'],
    text: '',
    sample: 'こんにちは 25.6℃ 薔薇',
  },
  { id: 'chineseUi', sets: ['ascii', 'hanCn1', 'symUnits'], text: '', sample: '你好 25.6℃ 温度' },
  { id: 'chineseTwUi', sets: ['ascii', 'hanTw1', 'symUnits'], text: '', sample: '你好 25.6℃ 溫度' },
  { id: 'koreanUi', sets: ['ascii', 'hangulKs', 'symUnits'], text: '', sample: '안녕하세요 25.6℃' },
  {
    id: 'multilingual',
    sets: ['ascii', 'latinExt', 'hiragana', 'katakana', 'jaPunct', 'hanAll', 'hangulAll', 'symUnits'],
    text: '',
    sample: 'こんにちは 你好 안녕하세요 25.6℃',
  },
];

export const templateById = (id) => TEMPLATES.find((t) => t.id === id) || null;

// --- resolving ------------------------------------------------------------

/**
 * Union of the selected sets, literal custom text and custom ranges.
 * Sorted, deduped, and stripped of characters that can never be drawn.
 */
export function resolveCharset({ sets = [], customText = '', customRanges = '' } = {}) {
  const out = new Set();
  for (const id of sets) for (const c of codepointsOfSet(id)) out.add(c);
  for (const c of codepointsOf(customText)) out.add(c);
  for (const c of parseRanges(customRanges)) out.add(c);
  // U+0000..U+001F and U+007F have no glyph; keeping them only wastes flash.
  return [...out].filter((c) => c >= 0x20 && c !== 0x7f).sort((a, b) => a - b);
}

/**
 * Apply a selection change, keeping tier ladders mutually exclusive.
 * Returns a new list; `on` false removes.
 */
export function toggleSet(sets, id, on) {
  const siblings = tierSiblings(id);
  const next = siblings ? sets.filter((s) => !siblings.includes(s)) : sets.filter((s) => s !== id);
  if (on) next.push(id);
  return next;
}

// U8g2 addresses glyphs with a uint16 encoding, so anything outside the BMP
// cannot be represented. Callers report these back rather than silently
// dropping them. (常用漢字 contains one such character, 𠮟 U+20B9F.)
export const splitBmp = (cps) => ({
  bmp: cps.filter((c) => c <= 0xffff),
  dropped: cps.filter((c) => c > 0xffff),
});

// --- migration ------------------------------------------------------------

// Recipes saved against the previous, efont-derived sets. Those sets were
// curated bundles that do not exist any more, so each maps to the closest
// combination of the sets that replaced them. Sizes shift slightly; the
// alternative — dropping the selection — would be worse.
const LEGACY = {
  ascii: ['ascii'],
  latin1: ['ascii', 'latinExt'],
  digits: ['digits'],
  units: ['symUnits', 'symMath', 'symArrows', 'symShapes'],
  clock: ['digits', 'jaPunct'],
  kana: ['hiragana', 'katakana', 'jaPunct'],
  jaMini: ['ascii', 'hiragana', 'katakana', 'jaPunct', 'hanJa1'],
  ja: ['ascii', 'latinExt', 'hiragana', 'katakana', 'jaPunct', 'hanJa4'],
  cjk: ['ascii', 'hanAll'],
  cn: ['ascii', 'hanCn2'],
  tw: ['ascii', 'hanTw2'],
  kr: ['ascii', 'hanKo2', 'hangulKs'],
};

/**
 * Normalize a stored selection: map any legacy ids onto current ones, drop
 * anything unrecognized, and keep at most one tier per ladder.
 */
export function migrateSets(sets = []) {
  const out = [];
  for (const id of sets) {
    for (const mapped of (SET_RANGES[id] !== undefined ? [id] : LEGACY[id] || [])) {
      if (!out.includes(mapped)) out.push(mapped);
    }
  }
  // A legacy selection can expand into two tiers of one ladder (jaMini AND ja).
  // The old ids meant a union, and tiers are cumulative, so the highest tier is
  // exactly that union — keep it and drop the rest.
  const best = new Map(); // ladder key -> chosen id
  for (const id of out) {
    const sib = tierSiblings(id);
    if (!sib) continue;
    const key = sib.join('|');
    const cur = best.get(key);
    if (cur === undefined || sib.indexOf(id) > sib.indexOf(cur)) best.set(key, id);
  }
  const kept = new Set(best.values());
  return out.filter((id) => {
    const sib = tierSiblings(id);
    return !sib || kept.has(id);
  });
}
